function loadDashboard(api, userId, callback) {
  // api.getUser / api.getOrders / api.getRecommendations are callback-style:
  //   fn(arg, (err, result) => ...)
  // Load the user, then their orders, then recommendations based on the
  // orders, and assemble a summary. Any error short-circuits to callback(err).
  api.getUser(userId, (err, user) => {
    if (err) {
      callback(err);
      return;
    }
    api.getOrders(user.id, (err2, orders) => {
      if (err2) {
        callback(err2);
        return;
      }
      api.getRecommendations(orders, (err3, recs) => {
        if (err3) {
          callback(err3);
          return;
        }
        callback(null, {
          user: user.name,
          orderCount: orders.length,
          recommendations: recs,
        });
      });
    });
  });
}

module.exports = { loadDashboard };

