const test = require("node:test");
const assert = require("node:assert");

const { loadDashboard } = require("./dashboard");

function makeApi(overrides = {}) {
  return {
    getUser(id, cb) {
      // canonical id differs from the lookup id on purpose
      setImmediate(() => cb(null, { id: "canon-" + id, name: "Ada" }));
    },
    getOrders(userId, cb) {
      setImmediate(() => cb(null, [{ id: 1, owner: userId }, { id: 2, owner: userId }]));
    },
    getRecommendations(orders, cb) {
      setImmediate(() => cb(null, ["r1"]));
    },
    ...overrides,
  };
}

function run(api, userId) {
  return new Promise((resolve, reject) => {
    loadDashboard(api, userId, (err, result) => (err ? reject(err) : resolve(result)));
  });
}

test("assembles the summary through the whole chain", async () => {
  const result = await run(makeApi(), "u1");
  assert.deepStrictEqual(result, { user: "Ada", orderCount: 2, recommendations: ["r1"] });
});

test("second call uses the canonical id from getUser, not the lookup id", async () => {
  let seenOwner = null;
  const api = makeApi({
    getOrders(userId, cb) {
      seenOwner = userId;
      setImmediate(() => cb(null, [{ id: 1 }]));
    },
  });
  await run(api, "u1");
  assert.strictEqual(seenOwner, "canon-u1", "getOrders must receive user.id, not the original userId");
});

test("an error anywhere short-circuits to the callback", async () => {
  const api = makeApi({
    getOrders(userId, cb) {
      setImmediate(() => cb(new Error("orders down")));
    },
  });
  await assert.rejects(run(api, "u1"), /orders down/);
});

