const { promisify } = require("node:util");

async function loadDashboard(api, userId, callback) {
  const getUser = promisify(api.getUser.bind(api));
  const getOrders = promisify(api.getOrders.bind(api));
  const getRecommendations = promisify(api.getRecommendations.bind(api));
  try {
    const user = await getUser(userId);
    const orders = await getOrders(user.id);
    const recs = await getRecommendations(orders);
    callback(null, {
      user: user.name,
      orderCount: orders.length,
      recommendations: recs,
    });
  } catch (err) {
    callback(err);
  }
}

module.exports = { loadDashboard };

